// Export Dune: Awakening DataTables to JSON with CUE4Parse, using a .usmap generated by tools/usmap_gen.
//
// usage: RecipeExport <paks-dir> <mappings.usmap> <oo2core_9_win64.dll> <package-filter> <out-dir> [mapstructs.json]
//        RecipeExport icons <paks-dir> <mappings.usmap> <oo2core_9_win64.dll> <site-data.json> <out-dir> [size]
//
// Funcom cooks DataTable rows with tagged properties, and tagged maps do not record the struct type of their
// keys and values. mapstructs.json (written by tools/usmap_gen --map-struct-types) supplies them by name.
using CUE4Parse.UE4.Versions;
using Newtonsoft.Json;
using Serilog;

var verbose = Environment.GetEnvironmentVariable("RECIPE_EXPORT_VERBOSE") == "1";
Log.Logger = new LoggerConfiguration()
    .MinimumLevel.Is(verbose ? Serilog.Events.LogEventLevel.Verbose : Serilog.Events.LogEventLevel.Warning)
    .WriteTo.Console()
    .CreateLogger();

if (args.Length > 0 && args[0] == "icons")
    return IconExport.Run(args[1..]);

if (args.Length < 5)
{
    Console.Error.WriteLine("usage: RecipeExport <paks-dir> <mappings.usmap> <oodle-dll> <package-filter> <out-dir>");
    return 2;
}

var (paksDir, usmapPath, oodleDll, filter, outDir) = (args[0], args[1], args[2], args[3], args[4]);
Directory.CreateDirectory(outDir);

Dictionary<string, KeyValuePair<string, string>>? mapStructTypes = null;
if (args.Length > 5)
{
    var table = JsonConvert.DeserializeObject<Dictionary<string, string?[]>>(File.ReadAllText(args[5]))!;
    mapStructTypes = table.ToDictionary(kv => kv.Key, kv => new KeyValuePair<string, string>(kv.Value[0]!, kv.Value[1]!));
    Console.WriteLine($"loaded {mapStructTypes.Count} map struct types");
}

var provider = GameFiles.Open(paksDir, usmapPath, oodleDll, mapStructTypes);

if (Environment.GetEnvironmentVariable("RECIPE_EXPORT_LANGUAGE") is { Length: > 0 } language)
{
    var count = provider.LoadLocalization(Enum.Parse<ELanguage>(language));
    Console.WriteLine($"loaded {count} localized strings ({language})");
}

// Several filters can be given separated by '|'; a package matches if its path contains any of them.
var filters = filter.Split('|', StringSplitOptions.RemoveEmptyEntries);
bool Matches(string path) => filters.Any(f => path.Contains(f, StringComparison.OrdinalIgnoreCase));

if (Environment.GetEnvironmentVariable("RECIPE_EXPORT_LIST_ONLY") == "1")
{
    foreach (var path in provider.Files.Keys.Where(Matches).Order())
        Console.WriteLine(path);
    return 0;
}

var packages = provider.Files.Keys
    .Where(k => k.EndsWith(".uasset", StringComparison.OrdinalIgnoreCase) && Matches(k))
    .ToList();
Console.WriteLine($"{packages.Count} package(s) match '{filter}'");

var debugRow = Environment.GetEnvironmentVariable("RECIPE_EXPORT_DEBUG_ROW");
var failures = 0;
foreach (var path in packages)
{
    try
    {
        if (Environment.GetEnvironmentVariable("RECIPE_EXPORT_SAVE_RAW") == "1")
        {
            foreach (var (name, bytes) in provider.SavePackage(path))
            {
                var rawFile = Path.Combine(outDir, Path.GetFileName(name) + ".raw");
                File.WriteAllBytes(rawFile, bytes);
                Console.WriteLine($"  raw  {name} -> {rawFile} ({bytes.Length} bytes)");
            }
        }
        var exports = provider.LoadPackage(path).GetExports().ToList();
        if (debugRow is not null)
        {
            foreach (var table in exports.OfType<CUE4Parse.UE4.Assets.Exports.Engine.UDataTable>())
                if (table.RowMap.FirstOrDefault(r => r.Key.Text == debugRow).Value is { } row)
                    DumpStruct(row, "  ");
        }
        var json = JsonConvert.SerializeObject(exports, Formatting.Indented);
        var outFile = Path.Combine(outDir, Path.GetFileNameWithoutExtension(path) + ".json");
        File.WriteAllText(outFile, json);
        Console.WriteLine($"  ok   {path} -> {outFile} ({json.Length / 1024} KB)");
    }
    catch (Exception e)
    {
        failures++;
        Console.WriteLine($"  FAIL {path}: {e.GetType().Name}: {e.Message}");
    }
}
return failures == 0 ? 0 : 1;

static void DumpStruct(CUE4Parse.UE4.Assets.Objects.FStructFallback value, string indent)
{
    foreach (var tag in value.Properties)
    {
        var detail = tag.Tag switch
        {
            CUE4Parse.UE4.Assets.Objects.Properties.MapProperty m => $"entries={m.Value?.Properties.Count}",
            CUE4Parse.UE4.Assets.Objects.Properties.ArrayProperty a => $"elements={a.Value?.Properties.Count}",
            _ => ""
        };
        Console.WriteLine($"{indent}{tag.Name.Text} [{tag.PropertyType.Text}] tag={tag.Tag?.GetType().Name ?? "null"} size={tag.Size} {detail}");
        if (tag.Tag is CUE4Parse.UE4.Assets.Objects.Properties.StructProperty { Value.StructType: CUE4Parse.UE4.Assets.Objects.FStructFallback inner })
            DumpStruct(inner, indent + "  ");
        if (tag.Tag is CUE4Parse.UE4.Assets.Objects.Properties.ArrayProperty { Value: { } arr })
            foreach (var element in arr.Properties)
                if (element is CUE4Parse.UE4.Assets.Objects.Properties.StructProperty { Value.StructType: CUE4Parse.UE4.Assets.Objects.FStructFallback e })
                    DumpStruct(e, indent + "    ");
    }
}
